scwin.onpageload = function () {

};

/**
 * @method  $p
 * @name    setDisabled 
 * @cdate   2014-03-11
 * @version 5.0
 * @author  seamelody
 * @description
 *  지정한 컴포넌트의 하위로 disabled를 처리한다.
 * @param   <JSON:Y> obj    disabled 설정이 담긴 객체 
 * |<String:N> obj.componentId :[default:body] 컴포넌트 Id, 비어있으면 body
 * |<boolean:Y> obj.disabled : [default:false, true] disabeld 적용 여부
 * |<Array<String>:N> obj.excludeIdList : 제외할 컴포넌트 Id가 담긴 Array (미입력시 전체 적용) 
 * |<Array<String>:N> obj.includeIdList : 허용할 컴포넌트 Id가 담긴 Array (미입력시 전체 적용)
 * @see
 * @return  <JSON> JSON형태의 값을 반환한다.
 * |<Array> object.doneComponents 완료한 컴포넌트 ID가 담긴 Array
 * |<Array> object.skipComponents 이미 disabled 처리되어 있어 Skip한 컴포넌트 ID가 담긴 Array 
 * @exception
 * @sample  
 * |$p.setDisabled({"disabled":true});      //전체 disabled
 * |$p.setDisabled({"disabled":false});     //전체 enabled
 * |$p.setDisabled({"componentId":"group1", "disabled":true});  //group1 하위의 컴포넌트를 disabled
 * |$p.setDisabled({"componentId":"", "disabled":true, "excludeIdList": ["output10"]}); //output10을 제외한 전체 disabled
 * |$p.setDisabled({"componentId":"", "disabled":true, "includeIdList": ["output1","output2"]});    //output1,output2만 disabled
 * @hidden  false
 * @deprecated
 */
scwin.sample_org = function () {

};

/**
 * @method  $p
 * @name    setDisabled 
 * @cdate   2014-03-11
 * @version 5.0
 * @author  seamelody
 * @description
 * 첫 번째 인자(obj)의 설정에 따라 컴포넌트를 비활성화(disabled)합니다.
 * @param   <JSON:Y> obj    disabled 설정이 담긴 객체 
 * |<String:N> obj.componentId :[default: body] 컴포넌트의 ID, 비어있으면 body
 * |<boolean:Y> obj.disabled : [default: false, true] disabeld 적용 여부
 * |<Array<String>:N> obj.excludeIdList : 제외할 컴포넌트의 ID가 담긴 배열
 * |<Array<String>:N> obj.includeIdList : 허용할 컴포넌트의 ID가 담긴 배열
 * @see
 * @return  <JSON> JSON 형태로 처리 결과를 반환합니다.
 * |<Array> object.doneComponents 완료한 컴포넌트 ID가 담긴 배열
 * |<Array> object.skipComponents 이미 비활성화되어 있어 Skip한 컴포넌트 ID가 담긴 배열
 * @exception
 * @sample  
 * |$p.setDisabled({"disabled":true});      //전체 disabled
 * |$p.setDisabled({"disabled":false});     //전체 enabled
 * |$p.setDisabled({"componentId":"group1", "disabled":true});  //group1 하위의 컴포넌트를 disabled
 * |$p.setDisabled({"componentId":"", "disabled":true, "excludeIdList": ["output10"]}); //output10을 제외한 전체 disabled
 * |$p.setDisabled({"componentId":"", "disabled":true, "includeIdList": ["output1","output2"]});    //output1,output2만 disabled
 * @hidden  false
 * @deprecated
 */
scwin.sample = function () {
    // 첫 번째 인자(obj)의 설정에 따라 컴포넌트를 비활성화(disabled)합니다.
};

/**
 * 버튼 [disabled >>> true]
 */
scwin.btn_exam1_1_onclick = function (e) {
    console.log("# 버튼 disabled >>> true");

    // var jsnResult = $p.setDisabled({
    //     "disabled": true
    // });

    // var jsnResult = $p.setDisabled({
    //     "disabled": true,
    //     "componentId" :  "wfm_exam1"
    // });

    // var jsnResult = $p.setDisabled({
    //     "disabled": true,
    //     "excludeIdList": ["btn_exam2_1"]
    // });

    // runtime id를 할당해야 정상 동작 됨.
    // var jsnResult = $p.setDisabled({
    //     "disabled": true,
    //     "includeIdList": ["mf_btn_exam1_2"]
    // });

    var jsnResult = $p.setDisabled({
        "disabled": true,
        "includeIdList": ["btn_exam2_1"]
    });

    console.log("jsnResult >>> ", jsnResult);
};

/**
 * 버튼 [disabled >>> false]
 */
scwin.btn_exam1_2_onclick = function (e) {
    console.log("# 버튼 disabled >>> false");

    var jsnResult = $p.setDisabled({
        "disabled": false
    });
    console.log("jsnResult >>> ", jsnResult);
};

/**
 * 버튼 [기능 테스트 용도]
 */
scwin.btn_exam2_1_onclick = function (e) {
    console.log("# 버튼기능 테스트 용도");

    var jsnResult = $p.setDisabled({
        "disabled": false
    });
    console.log("jsnResult >>> ", jsnResult);
};


	scwin.checkVal = function() {
		return WebSquare.wUnit.getJq('#btn_exam2_1').hasClass('w2trigger_disabled');
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_exam1_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
